"use strict";

// The package's whole callable API is chosen AT RUNTIME by a resolvable
// LOCAL CALL whose own body always throws -- but, unlike RWF-016's
// through RWF-022's fixtures, the call sits in no class-related position
// at all. It is an OBJECT LITERAL's COMPUTED KEY:
//
//     const mode = { [bail()]: 1 };
//
// For every property in an object literal's PropertyDefinitionList, in
// source order, the computed key expression is evaluated and converted to
// a property key BEFORE that property's value (or the method/getter/setter
// it names) is installed on the new object. That is true for every element
// form, and it happens whether or not any `class` appears anywhere in the
// file. See
// fixtures/commonjs-circular-import-object-literal-computed-key-throw-ground-truth/
// for a real node-executed proof.
const danger = require("./danger");

// The branch that reaches the vulnerable sink. Nothing in this file calls
// it: the ONLY way it ever runs is by being the module's exported value.
function dangerousOp(input) {
  return danger.explode(input);
}

// The branch that does not.
function safeOp(input) {
  return "safe:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw -- definitely abrupt by RWF-016's own model, unchanged.
function bail() {
  throw new Error("fast mode is not supported here");
}

// A harmless local callable, so that key evaluation ORDER is exercised
// rather than assumed.
function tag() {
  return "tag";
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  // Computed keys evaluate in source order as part of evaluating the
  // object literal, so `[tag()]` evaluates and then this necessarily
  // invokes `bail()`. It never returns, the third key is never evaluated,
  // the object literal never finishes constructing, `mode` is never
  // bound, and module evaluation on this branch ends here.
  const mode = {
    [tag()]: "fast",
    [bail()]: 1,
    [tag()]: "never evaluated",
  };
  void mode;
}

module.exports = safeOp;
